#include <iostream>
#include <cstdio>
#include <cmath>
#include <cstring>
#include <algorithm>
using namespace std;

int n_value, k_value, mod_value;
long long factorials[250003], invs[250003];
long long cache[27][250003];

int lowbit(int x) { return x & (-x); }

long long fast_pow(long long base, int exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod_value;
        base = base * base % mod_value;
        exp >>= 1;
    }
    return result;
}

void setup() {
    factorials[0] = 1;
    for (int i = 1; i <= n_value; ++i)
        factorials[i] = factorials[i - 1] * i % mod_value;
    invs[n_value] = fast_pow(factorials[n_value], mod_value - 2);
    for (int i = n_value - 1; i >= 0; --i)
        invs[i] = invs[i + 1] * (i + 1) % mod_value;
}

long long solve(int x, int s) {
    if (cache[x][s] != -1) return cache[x][s];
    if (s == 0) return cache[x][s] = factorials[n_value] * factorials[k_value] % mod_value * invs[k_value - x] % mod_value;
    int remaining = s - lowbit(s);
    long long sum = 0;
    for (int t = remaining; t; t = (t - 1) & remaining)
        sum = (sum + solve(x + 1, t) * invs[s - t]) % mod_value;
    sum = (sum + solve(x + 1, 0) * invs[s]) % mod_value;
    return cache[x][s] = sum;
}

int main() {
    scanf("%d %d %d", &n_value, &k_value, &mod_value);
    setup();
    long long ans = fast_pow(k_value, n_value);
    if (n_value % 2 == 0) {
        memset(cache, -1, sizeof(cache));
        ans = (ans - solve(0, n_value) + mod_value) % mod_value;
    }
    printf("%lld", ans);
    return 0;
}
